<?php namespace App\Repositories\MongoDB; use App\Repositories\Interfaces\ContactRepositoryInterface; use MongoDB\BSON\UTCDateTime;
final class MongoContactRepository extends MongoRepository implements ContactRepositoryInterface { private function c(){return $this->db->db()->contacts;} public function all():array{return $this->rows($this->c()->find([],['sort'=>['created_at'=>-1]]));} public function find(string $id):?array{$x=$this->c()->findOne(['_id'=>$this->id($id)]);return $x?$this->row($x):null;} public function save(array $d):string{$d['created_at']=new UTCDateTime();return (string)$this->c()->insertOne($d)->getInsertedId();} public function delete(string $id):bool{return $this->c()->deleteOne(['_id'=>$this->id($id)])->getDeletedCount()===1;} public function count():int{return $this->c()->countDocuments();} }
